def seed_opentdb_questions():
    """Idempotent: INSERT OR IGNORE against question_text unique index."""
    ph = get_placeholder()
    added = 0
    for q in OPENTDB_QUESTIONS:
        cat = get_category_by_name(q["category"])
        if not cat:
            continue
        try:
            execute_query(f"""
                INSERT OR IGNORE INTO trivia_questions
                (category_id, question_text, setup_text, answer_a, answer_b, answer_c, answer_d,
                 correct_answer, difficulty, time_limit, explanation,
                 host_commentary_correct, host_commentary_wrong)
                VALUES ({ph}, {ph}, {ph}, {ph}, {ph}, {ph}, {ph}, {ph}, {ph}, {ph}, {ph}, {ph}, {ph})
            """, (
                cat["id"], q["question"], q.get("setup", ""),
                q["answers"]["A"], q["answers"]["B"], q["answers"]["C"], q["answers"]["D"],
                q["correct"], q["difficulty"], q["time_limit"],
                q.get("explanation", ""), q.get("commentary_correct", ""), q.get("commentary_wrong", ""),
            ))
            added += 1
        except Exception as e:
            print(f"[opentdb seed] {e}")
    print(f"\u2705 OpenTDB seeder added {added} new questions (of {len(OPENTDB_QUESTIONS)})")
